namespace Nuzul;

public class Project { public bool Archived { get; set; } public string ArchiveReason { get; set; } = ""; public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string Name { get; set; } = ""; public List<Source> Sources { get; set; } = []; public List<Requirement> Requirements { get; set; } = []; public List<TestCase> TestCases { get; set; } = []; public List<Run> Runs { get; set; } = []; public List<Defect> Defects { get; set; } = []; public Settings Settings { get; set; } = new(); }
public class Source { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string Type { get; set; } = "text"; public string Name { get; set; } = ""; public string Content { get; set; } = ""; }
public class Requirement { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string SourceId { get; set; } = ""; public string Reference { get; set; } = ""; public string Text { get; set; } = ""; public string Status { get; set; } = "Verified"; }
public class TestCase { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string Title { get; set; } = ""; public string RequirementId { get; set; } = ""; public List<string> Preconditions { get; set; } = []; public string InputData { get; set; } = ""; public List<string> Steps { get; set; } = []; public string ExpectedResult { get; set; } = ""; public string Priority { get; set; } = "High"; public string TestType { get; set; } = "API"; public string ExecutionMode { get; set; } = "Automated"; public string Language { get; set; } = "csharp"; public string VerificationStatus { get; set; } = "Needs Review"; public bool Approved { get; set; } public bool Excluded { get; set; } public string Method { get; set; } = "GET"; public string Path { get; set; } = ""; public string Body { get; set; } = ""; public int? ExpectedStatus { get; set; } public List<Assertion> Assertions { get; set; } = []; }
public class Assertion { public string Kind { get; set; } = "status"; public string Path { get; set; } = ""; public string Expected { get; set; } = ""; }
public class Settings { public string BaseUrl { get; set; } = ""; public string Language { get; set; } = "csharp"; public bool AllowMutations { get; set; } public string AuthToken { get; set; } = ""; }
public class Run { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string ProjectId { get; set; } = ""; public string Status { get; set; } = "Running"; public string Language { get; set; } = "csharp"; public DateTimeOffset StartedAt { get; set; } = DateTimeOffset.UtcNow; public List<ExecutionRecord> Results { get; set; } = []; public List<TestCase> TestCasesSnapshot { get; set; } = []; public List<Requirement> RequirementsSnapshot { get; set; } = []; public string TargetSnapshot { get; set; } = ""; }
public class ExecutionRecord { public string TestCaseId { get; set; } = ""; public string Outcome { get; set; } = "Blocked"; public RequestEvidence Request { get; set; } = new(); public ResponseEvidence Response { get; set; } = new(); public string ExpectedResult { get; set; } = ""; public string ActualResult { get; set; } = ""; public string AssertionOutcome { get; set; } = "Not executed"; public double DurationMs { get; set; } public DateTimeOffset Timestamp { get; set; } = DateTimeOffset.UtcNow; public string ErrorDetails { get; set; } = ""; public string EvidenceReference { get; set; } = ""; public string Observations { get; set; } = ""; public string AttachedEvidence { get; set; } = ""; public string ReviewedOutcome { get; set; } = ""; public bool Reviewed { get; set; } }
public class RequestEvidence { public string Method { get; set; } = ""; public string Url { get; set; } = ""; public string Body { get; set; } = ""; }
public class ResponseEvidence { public int Status { get; set; } public string Body { get; set; } = ""; }
public class RunnerInput { public string BaseUrl { get; set; } = ""; public string AuthToken { get; set; } = ""; public bool AllowMutations { get; set; } public List<TestCase> Tests { get; set; } = []; }
public class ProviderSettings { public string ProviderUrl { get; set; } = "https://api.openai.com/v1/chat/completions"; public string Model { get; set; } = ""; public string ApiKey { get; set; } = ""; public bool Enabled { get; set; } }

public class Defect { public string EvidenceReference { get; set; } = ""; public string BugId { get; set; } = ""; public string Title { get; set; } = ""; public string Description { get; set; } = ""; public string Severity { get; set; } = "Needs triage"; public string Priority { get; set; } = "High"; public string Status { get; set; } = "Open"; public List<string> ReproductionSteps { get; set; } = []; }
